import requests
import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url:
        raise ValueError("A valid repository URL string is required.")

    try:
        response = requests.get(repo_url, timeout=10)
        response.raise_for_status()

        data = response.json()

        if data.get("open_issues_count", 0) > 100:
            logging.warning("Repository has a high number of open issues.")

        return data

    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 403:
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded or access forbidden.")
        raise e
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"An error occurred while fetching repository data: {e}")

